INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Tracking', 'How do I track my shipment?', 'Sign in to your account and enter your tracking ID or container number in the tracking box. You will see the current status, location and the full timeline.', 1, 10, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(2, 'Tracking', 'Where do I find my tracking ID?', 'We email it to you when your shipment is added to your account. It is also listed on your dashboard.', 1, 20, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(3, 'Tracking', 'Why has my shipment status not changed?', 'Ocean shipments can spend several days between ports. If you are worried, contact us and we will check with the carrier.', 1, 30, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(4, 'Account', 'Why can I not sign in after registering?', 'New accounts are reviewed by our team and activated after approval. You will get an email as soon as yours is approved.', 1, 40, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(5, 'Account', 'Can I see shipments from other people?', 'No. You can only see shipments that are assigned to your own account.', 1, 50, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(6, 'Shipping', 'How long does shipping take?', 'It depends on the route and service. Air freight usually takes days, sea freight takes weeks. Your quote shows the expected transit time.', 1, 60, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(7, 'Shipping', 'What documents do I need?', 'Usually a commercial invoice, packing list and bill of lading or air waybill. Some goods need permits or certificates. See our shipping guide.', 1, 70, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(8, 'Shipping', 'Can you ship dangerous or restricted goods?', 'Some can be shipped with special handling and paperwork. Tell us about the goods when you request a quote.', 1, 80, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(9, 'Pricing', 'How do I get a quote?', 'Use the quote form with your cargo, origin and destination. We will reply with pricing and transit time.', 1, 90, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(10, 'Pricing', 'Is cargo insurance included?', 'Not by default. We recommend insuring your goods and can arrange cover for you.', 1, 100, '2026-11-13 14:17:11', '2026-11-13 14:17:11');
INSERT INTO `pages` (`id`, `slug`, `title`, `subtitle`, `body`, `header_image`, `meta_description`, `kind`, `is_published`, `show_in_menu`, `show_in_footer`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'about', 'About us', 'A freight partner you can follow every step of the way.', 'Global Shipping Alliance is a freight forwarding and cargo tracking company. We help importers and exporters move goods by sea, air and road, and we keep every client informed from the port of origin to the final delivery address.\n\n## What we believe\n\nMoving cargo should not feel like a black box. Our clients get a personal account where they can see where each shipment is, what happens next and when it is expected. When something changes, we email you straight away.\n\n## How we work\n\n- **One point of contact.** We coordinate carriers, ports, customs and local delivery so you do not have to.\n- **Clear communication.** Status and location updates are logged against every shipment and visible in your dashboard.\n- **Honest advice.** We recommend the mode and route that fit your cargo, budget and deadline.\n\n## Get started\n\nRequest a quote, or register for a client account to follow your shipments online.', NULL, NULL, 'system', 1, 1, 1, 10, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(2, 'company-profile', 'Company profile', 'Our mission, vision and values.', '## Mission\n\nTo make international freight simple, transparent and dependable for businesses of every size.\n\n## Vision\n\nTo be the forwarder clients trust first, because they always know where their cargo is.\n\n## Our values\n\n- **Transparency:** you see what we see.\n- **Reliability:** we do what we say, when we say it.\n- **Care:** every container carries someone\'s business.\n- **Compliance:** we respect customs, safety and trade regulations on every route.\n\n## Company details\n\nRegistered name, registration number, VAT number and bank details can be added here by the administrator.', NULL, NULL, 'content', 1, 0, 1, 20, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(3, 'how-it-works', 'How it works', 'From first enquiry to delivery in four steps.', '## 1. Tell us what you are shipping\n\nSend us the cargo description, origin, destination and your target dates through the quote form.\n\n## 2. Receive your quote\n\nWe reply with the recommended service, transit time and pricing, and explain what is included.\n\n## 3. We move your cargo\n\nWe book space, prepare the documents, clear customs and coordinate transport. Each step is recorded on your shipment timeline.\n\n## 4. Track and receive\n\nSign in to your dashboard or use the tracking box on the home page with your tracking ID or container number. You get an email each time your shipment moves.', NULL, NULL, 'content', 1, 0, 1, 30, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(4, 'shipping-guide', 'Shipping guide', 'Documents, terms and tips every shipper should know.', '## Documents you will usually need\n\n- Commercial invoice\n- Packing list\n- Bill of lading (sea) or air waybill (air)\n- Import or export permits where applicable\n- Certificate of origin when claiming preferential duty\n\n## Common shipping terms (Incoterms)\n\n| Term | Who arranges main carriage | Typical use |\n| --- | --- | --- |\n| EXW | Buyer | Buyer collects at the seller\'s premises |\n| FOB | Buyer | Seller loads onto the vessel at the origin port |\n| CIF | Seller | Seller pays freight and insurance to the destination port |\n| DAP | Seller | Seller delivers to the named place, buyer clears import |\n\nAlways confirm the exact term and the Incoterms edition in your contract.\n\n## Packing tips\n\n1. Use strong, clean packaging suited to the journey.\n2. Label every package clearly on more than one side.\n3. Do not exceed the weight limits of the container or pallet.\n4. Insure goods of value.', NULL, NULL, 'content', 1, 0, 1, 40, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(5, 'terms-and-conditions', 'Terms and conditions', 'The terms that apply when you use our services and this website.', '*Starter text. Have it reviewed by a legal adviser and replace company details before relying on it.*\n\n## 1. About these terms\n\nThese terms apply to all quotes, services and use of the Global Shipping Alliance website. By requesting a quote, creating an account or using our services you agree to them.\n\n## 2. Quotes and bookings\n\nQuotes are estimates based on the information you give us and are valid for the period stated on the quote. Rates can change if the cargo, route, carrier charges, exchange rates or fuel surcharges change.\n\n## 3. Your responsibilities\n\nYou must give accurate and complete information about the cargo, including its nature, weight, value and any dangerous goods. You are responsible for the legality of the goods and for the correctness of customs documents you supply.\n\n## 4. Transit times\n\nEstimated delivery dates are not guaranteed. Delays can result from weather, port congestion, customs inspections, strikes and other events outside our control.\n\n## 5. Liability and insurance\n\nOur liability is limited as set out in our written trading conditions and applicable law. We recommend that you insure your cargo. Claims must be notified in writing within the period stated in those conditions.\n\n## 6. Payment\n\nInvoices are payable by the due date on the invoice. We may hold cargo until amounts due are paid, as the law allows.\n\n## 7. Client accounts\n\nAccounts are activated after approval. You are responsible for keeping your password secret and for activity under your account. We may suspend accounts that are misused.\n\n## 8. Website use\n\nThe tracking information shown on this website is provided for convenience and may be delayed. Do not rely on it as a legal record.\n\n## 9. Changes\n\nWe may update these terms. The version on this page is the current one.\n\n## 10. Contact\n\nQuestions about these terms: use the contact page.', NULL, NULL, 'content', 1, 0, 1, 90, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(6, 'privacy-policy', 'Privacy policy', 'How we collect, use and protect your personal information.', '*Starter text. Have it reviewed by a legal adviser (for example against POPIA in South Africa) before relying on it.*\n\n## What we collect\n\n- **Account details:** name, username, email, phone, company and address.\n- **Shipment details:** cargo, routes and status updates linked to your account.\n- **Messages and quote requests** you send through our forms.\n- **Newsletter email address,** if you subscribe.\n\n## How we use it\n\nTo provide and track shipments, to communicate with you about your cargo, to respond to enquiries and, if you subscribed, to send news. We do not sell your personal information.\n\n## Who sees it\n\nOur staff, and carriers, agents and authorities where needed to move or clear your cargo, and service providers who host the website or send email for us.\n\n## Your choices\n\nYou can ask to see, correct or delete your information, and you can unsubscribe from the newsletter at any time using the link in our emails.\n\n## Cookies\n\nThe site uses essential cookies to keep you signed in and to protect forms.\n\n## Contact\n\nUse the contact page for any privacy request.', NULL, NULL, 'content', 1, 0, 1, 91, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(7, 'services', 'Our services', 'Sea, air and road freight, customs and warehousing under one roof.', NULL, NULL, NULL, 'system', 1, 1, 0, 20, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(8, 'faqs', 'Frequently asked questions', 'Quick answers about shipping, documents, tracking and your account.', NULL, NULL, NULL, 'system', 1, 0, 0, 50, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(9, 'testimonials', 'Client testimonials', 'What importers and exporters say about working with us.', NULL, NULL, NULL, 'system', 1, 0, 0, 51, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(10, 'team', 'Meet the team', 'The people who look after your cargo.', NULL, NULL, NULL, 'system', 1, 0, 0, 52, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(11, 'clients', 'Clients & partners', 'The businesses and carriers we work with.', NULL, NULL, NULL, 'system', 1, 0, 0, 53, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(12, 'news', 'News & updates', 'Port updates, industry news and shipping tips.', NULL, NULL, NULL, 'system', 1, 1, 0, 60, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(13, 'contact', 'Contact us', 'Questions about a shipment or a quote? We reply fast.', NULL, NULL, NULL, 'system', 1, 1, 0, 70, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(14, 'quote', 'Request a quote', 'Tell us about your cargo and route.', NULL, NULL, NULL, 'system', 1, 0, 0, 71, '2026-11-13 14:17:11', '2026-11-13 14:17:11');
