INSERT INTO `services` (`id`, `slug`, `title`, `summary`, `body`, `icon`, `image`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'sea-freight', 'Sea freight', 'Full container (FCL) and shared container (LCL) shipping on major trade lanes.', '## Full and shared containers\n\nMove large volumes in a dedicated 20ft or 40ft container (FCL), or share container space and pay only for the volume you use (LCL).\n\n## What is included\n\n- Booking with the shipping line\n- Bill of lading and documentation\n- Port handling and customs coordination\n- Delivery to your door, or collection from the port\n\n## Good to know\n\nSea freight is the most economical option for heavy or bulky cargo when time is not critical.', 'ship', NULL, 1, 10, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(2, 'air-freight', 'Air freight', 'Fast, reliable air cargo for urgent and high-value shipments.', '## When speed matters\n\nAir freight gets time-sensitive, perishable or high-value goods across the world in days instead of weeks.\n\n## What is included\n\n- Airline space booking and air waybill\n- Airport handling and security screening coordination\n- Customs clearance support\n- Door-to-door options\n\n## Good to know\n\nPricing is based on the greater of actual or volumetric weight.', 'plane', NULL, 1, 20, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(3, 'road-freight', 'Road freight', 'Local, cross-border and regional trucking with clear tracking.', '## Reliable overland transport\n\nFrom port to warehouse to your customer\'s door, and across borders in the region.\n\n## What is included\n\n- Full and part truck loads\n- Port collections and deliveries\n- Cross-border documentation support\n- Delivery updates logged on your shipment timeline', 'truck', NULL, 1, 30, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(4, 'customs-clearance', 'Customs clearance', 'Import and export clearance handled correctly and on time.', '## Avoid delays at the border\n\nCorrect classification and paperwork keep your cargo moving. We help you prepare and submit the documents customs requires.\n\n## What is included\n\n- Tariff classification guidance\n- Duty and VAT calculations\n- Import and export declarations\n- Permits and certificates coordination', 'doc', NULL, 1, 40, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(5, 'warehousing', 'Warehousing & distribution', 'Secure storage, pick and pack, and onward delivery.', '## Store, consolidate and distribute\n\nHold stock close to the port, consolidate smaller consignments, and release goods to your customers as needed.\n\n## What is included\n\n- Secure, monitored storage\n- Receiving, put-away and stock checks\n- Pick, pack and dispatch\n- Cross-docking for fast turnaround', 'warehouse', NULL, 1, 50, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(6, 'project-cargo', 'Project & heavy cargo', 'Planning and moving oversized, heavy or out-of-gauge equipment.', '## Specialist moves\n\nMachinery, plant and project equipment need careful route planning, special equipment and permits.\n\n## What is included\n\n- Route and equipment planning\n- Breakbulk and out-of-gauge shipping\n- Lifting, lashing and securing guidance\n- Escort and permit coordination', 'anchor', NULL, 1, 60, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(7, 'cargo-insurance', 'Cargo insurance', 'Protect the value of your goods while they are in transit.', '## Peace of mind\n\nCarrier liability is usually limited. Cargo insurance covers the value of your goods against loss or damage during transit.\n\n## What to tell us\n\nCargo value, packaging, route and dates so we can arrange suitable cover.', 'shield', NULL, 1, 70, '2026-11-13 14:17:11', '2026-11-13 14:17:11'),
(8, 'door-to-door', 'Door-to-door delivery', 'One partner for the whole journey, from supplier to final address.', '## One contract, one contact\n\nWe combine origin collection, main carriage, clearance and final delivery into a single service with one point of contact and one tracking ID.\n\n## Why clients choose it\n\n- Fewer hand-offs and fewer surprises\n- Clear status at every stage\n- One invoice', 'globe', NULL, 1, 80, '2026-11-13 14:17:11', '2026-11-13 14:17:11');
